<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { buscarSeguimiento, detallarSeguimiento, obtenerOpcionesFlujo, type SeguimientoFilters } from '../services/flujo'
import type { CatalogOption, DocumentoSeguimiento, SeguimientoDetalle } from '../../interfaces/documento'
const filters=reactive<SeguimientoFilters>({filtro_documento:'',filtro_remitente:'',tipo_documento_id:0,page:1})
const items=ref<DocumentoSeguimiento[]>([]),tipos=ref<CatalogOption[]>([]),context=reactive<{instancia?:CatalogOption|null;cargo?:CatalogOption|null}>({})
const pagination=reactive({current:1,last:1,total:0}),loading=ref(false),searched=ref(false),error=ref(''),detailLoading=ref(false),detail=ref<SeguimientoDetalle|null>(null)
function hasCriteria(){return Boolean(filters.filtro_documento.trim()||filters.filtro_remitente.trim()||filters.tipo_documento_id)}
async function search(page=1){if(!hasCriteria()){error.value='Debe especificar al menos un criterio de búsqueda.';return}filters.page=page;loading.value=true;searched.value=true;error.value='';try{const r=await buscarSeguimiento(filters);items.value=r.data;tipos.value=r.tipos_documento;context.instancia=r.contexto.instancia_activa;context.cargo=r.contexto.cargo_activo;Object.assign(pagination,{current:r.current_page,last:r.last_page,total:r.total})}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo consultar el flujo documentario.'}finally{loading.value=false}}
function clear(){Object.assign(filters,{filtro_documento:'',filtro_remitente:'',tipo_documento_id:0,page:1});items.value=[];searched.value=false;error.value=''}
async function openDetail(id:number){detailLoading.value=true;error.value='';try{detail.value=await detallarSeguimiento(id)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo cargar el seguimiento.'}finally{detailLoading.value=false}}
function number(d:DocumentoSeguimiento){return d.numero_completo||d.numero||`Documento #${d.id}`}
function current(d:DocumentoSeguimiento){return d.historial?.[0]}
function date(v?:string|null){if(!v)return'—';const parsed=new Date(v);return Number.isNaN(parsed.getTime())?v:new Intl.DateTimeFormat('es-PE',{dateStyle:'medium',timeStyle:'short'}).format(parsed)}
function stateClass(value?:string|null){const v=(value||'').toLowerCase();if(v.includes('archiv'))return'archived';if(v.includes('rechaz')||v.includes('anulad'))return'rejected';if(v.includes('recibid'))return'received';if(v.includes('sin recibir'))return'sent';return'pending'}
onMounted(async()=>{try{const r=await obtenerOpcionesFlujo();tipos.value=r.tipos_documento;context.instancia=r.contexto.instancia_activa;context.cargo=r.contexto.cargo_activo}catch{/* Los filtros se cargarán con la primera consulta. */}})
</script>
<template><div class="tracking"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/tramite">Trámite V2</RouterLink> / Flujo documentario / Seguimiento</nav><header class="hero"><div class="mark">TR</div><div><small>Flujo documentario</small><h1>Seguimiento de documentos</h1><p>Localiza un documento y revisa cada movimiento realizado durante su trámite.</p></div><aside v-if="context.instancia"><b>{{context.instancia.nombre}}</b><span>{{context.cargo?.nombre||'Cargo activo'}}</span></aside></header><form class="filters" @submit.prevent="search()"><header><b>Consultar seguimiento</b><span>Ingresa por lo menos uno de los criterios disponibles.</span></header><div class="filter-grid"><label><span>ID, código único o número</span><input v-model.trim="filters.filtro_documento" placeholder="Ej. 123 o MEM-2026-001"></label><label><span>Documento o nombre del remitente</span><input v-model.trim="filters.filtro_remitente" placeholder="DNI, RUC o nombres"></label><label><span>Tipo de documento</span><select v-model="filters.tipo_documento_id"><option :value="0">Todos</option><option v-for="o in tipos" :key="o.id" :value="o.id">{{o.nombre}}</option></select></label></div><footer><button type="submit">Buscar documento</button><button type="button" class="clear" @click="clear">Limpiar</button></footer></form><div v-if="error" class="alert">{{error}}</div><div v-if="loading" class="notice">Consultando flujo documentario…</div><div v-else-if="searched&&!items.length" class="notice"><b>No se encontraron documentos</b><span>Verifica los datos e intenta con otro criterio.</span></div><div v-else-if="!searched" class="welcome"><div>⌕</div><h2>Consulta el recorrido de un documento</h2><p>El resultado mostrará su estado actual, ubicación y acceso a la línea de tiempo completa.</p></div><section v-else class="results"><header><div><small>Resultados</small><h2>Documentos encontrados</h2></div><strong>{{pagination.total}} documentos</strong></header><article v-for="d in items" :key="d.id"><div class="doc-icon">▤</div><div class="identity"><small>{{d.tipo_documento?.nombre||'Documento'}} · #{{d.id}}</small><h3>{{number(d)}}</h3><p>{{d.asunto}}</p><span v-if="d.remitente">Remitente: {{d.remitente}}</span></div><div class="route"><span>Origen</span><b>{{current(d)?.instancia_origen?.nombre||'—'}}</b><i>→</i><span>Ubicación actual</span><b>{{current(d)?.instancia_destino?.nombre||'—'}}</b></div><div class="current"><span :class="stateClass(current(d)?.estado)">{{current(d)?.estado||d.estado||'Sin estado'}}</span><small>{{date(current(d)?.updated_at||current(d)?.created_at||d.created_at)}}</small></div><button :disabled="detailLoading" @click="openDetail(d.id)">Ver flujo</button></article></section><footer v-if="pagination.last>1" class="pagination"><button :disabled="pagination.current===1" @click="search(pagination.current-1)">Anterior</button><span>Página {{pagination.current}} de {{pagination.last}}</span><button :disabled="pagination.current===pagination.last" @click="search(pagination.current+1)">Siguiente</button></footer><div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal"><header><div class="mark small">TR</div><div><small>Seguimiento completo</small><h2>{{number(detail.documento)}}</h2><p>{{detail.documento.asunto}}</p></div><button @click="detail=null">×</button></header><div class="summary"><span><small>Tipo</small><b>{{detail.documento.tipo_documento?.nombre||'—'}}</b></span><span><small>Código único</small><b>{{detail.documento.codigo_unico||detail.historial[0]?.codigounico||'—'}}</b></span><span><small>Prioridad</small><b>{{detail.documento.prioridad||'Normal'}}</b></span><span><small>Movimientos</small><b>{{detail.historial.length}}</b></span></div><div class="timeline"><article v-for="(h,index) in detail.historial" :key="h.id"><div class="line"><i :class="stateClass(h.estado)"></i></div><div class="event"><header><span :class="stateClass(h.estado)">{{h.estado}}</span><time>{{date(h.fecha_recepcion||h.created_at)}}</time></header><div class="movement"><div><small>Origen</small><b>{{h.instancia_origen?.nombre||'—'}}</b><span>{{h.cargo_origen?.nombre||h.usuario_origen?.nombre||''}}</span></div><i>→</i><div><small>Destino</small><b>{{h.instancia_destino?.nombre||'—'}}</b><span>{{h.cargo_destino?.nombre||h.usuario_destino?.nombre||''}}</span></div></div><dl v-if="h.proveido||h.indicacion||h.observacion"><div v-if="h.proveido"><dt>Proveído</dt><dd>{{h.proveido}}</dd></div><div v-if="h.indicacion"><dt>Indicación</dt><dd>{{h.indicacion}}</dd></div><div v-if="h.observacion"><dt>Observación</dt><dd>{{h.observacion}}</dd></div></dl><small class="step">Movimiento {{index+1}}</small></div></article></div><div v-if="detail.anexos.length||detail.referencias.length" class="related"><section v-if="detail.anexos.length"><h3>Anexos ({{detail.anexos.length}})</h3><div v-for="a in detail.anexos" :key="a.id"><b>{{a.nombre_original}}</b><span>{{a.extension?.toUpperCase()}} {{a.tamano_formateado}}</span></div></section><section v-if="detail.referencias.length"><h3>Referencias ({{detail.referencias.length}})</h3><div v-for="r in detail.referencias" :key="r.id"><b>{{r.numero||`Documento #${r.id}`}}</b><span>{{r.asunto}}</span></div></section></div></section></div></div></template>
